entries[63472] = { ["name"] = "Flammenstrahlen", ["text"] = "Wirken in 2.7 sek.\nStampft auf den Boden, wodurch sich Flammengeysire unter allen Feinden öffnen. Diese Geysire verursachen 0 Feuerschaden, schleudern die Ziele in die Luft und unterbrechen 6 Sek. lang alle gewirkten Zauber. Zusätzlich erleiden die Ziele 6 Sek. lang 0 Feuerschaden pro Sekunde." }
